double polygonArea(vector<Point>& p) {
    int n = p.size();
    long long sum = 0;
    for (int i = 0; i < n; i++) {
        Point a = p[i], b = p[(i + 1) % n];   // wrap around at the end
        sum += a.x * b.y - b.x * a.y;          // cross product of the pair
    }
    return llabs(sum) / 2.0;
}

