double polygonArea(long[][] p) {
    int n = p.length;
    long sum = 0;
    for (int i = 0; i < n; i++) {
        long[] a = p[i], b = p[(i + 1) % n];   // wrap around at the end
        sum += a[0] * b[1] - b[0] * a[1];      // cross product of the pair
    }
    return Math.abs(sum) / 2.0;
}

