function polygonArea(p) {
  const n = p.length;
  let sum = 0;
  for (let i = 0; i < n; i++) {
    const a = p[i], b = p[(i + 1) % n];   // wrap around at the end
    sum += a[0] * b[1] - b[0] * a[1];      // cross product of the pair
  }
  return Math.abs(sum) / 2;
}
